/// <summary>
/// Extension of class <c>FreeTextInvoiceDP</c>
/// </summary>
[ExtensionOf(classStr(FreeTextInvoiceDP))]
final class KPMGFreeTextInvoiceDP_Extension
{
    #Define.WET('WET') 
}

Method.Source:
    /// <summary>
    /// Populates the invoice header information into the <c>FreeTextInvoiceHeaderFooterTmp</c> table buffer.
    /// </summary>
    /// <param name="_custInvoiceJour">
    /// The <c>CustInvoiceJour</c> record that has the invoice header information.
    /// </param>
    /// <param name="_companyInfo">
    /// The <c>CompanyInfo</c> record that has the company information.
    /// </param>
    protected void populateFreeTextInvoiceHeaderFooterTmp(CustInvoiceJour _custInvoiceJour, CompanyInfo _companyInfo)
    {        
        next populateFreeTextInvoiceHeaderFooterTmp (_custInvoiceJour , _companyInfo);
        
        freeTextInvoiceHeaderFooterTmp.CompanyEmail = _companyInfo.email();
        freeTextInvoiceHeaderFooterTmp.KPMGCashDiscCodeDesc = CashDisc::find(_custInvoiceJour.CashDiscCode).Description;

        freeTextInvoiceHeaderFooterTmp.KPMGPurchOrderFormNum = _custInvoiceJour.PurchaseOrder;

        //MPJ_6030_7435_FreeTextInvReportDesign - START
        TaxTrans                        taxTransWET;
        LogisticsElectronicAddress      electronicAddress;
        DirPartyLocation                partyLocation;
        LogisticsElectronicAddressRole  leaRole;
        LogisticsLocationRole           locationRole;
        BankAccountTable                metBankAccountTable = BankAccountTable::find(_companyInfo.Bank);

        freeTextInvoiceHeaderFooterTmp.CompanyBankAccount = metBankAccountTable.AccountNum;
        freeTextInvoiceHeaderFooterTmp.CompanyRegNum = metBankAccountTable.RegistrationNum;
        freeTextInvoiceHeaderFooterTmp.KPMGLicenseNum = CustTable::find(_custInvoiceJour.InvoiceAccount).PackMaterialFeeLicenseNum;

        select firstonly Locator from electronicAddress
                where electronicAddress.Type == LogisticsElectronicAddressMethodType::Phone
                exists join partyLocation
                    where partyLocation.Location == electronicAddress.Location
                        && partyLocation.Party == _companyInfo.RecId
                        && partyLocation.IsPostalAddress == NoYes::No
                exists join leaRole
                    where leaRole.ElectronicAddress == electronicAddress.RecId
                exists join locationRole
                    where locationRole.RecId == leaRole.LocationRole
                        && locationRole.Type == LogisticsLocationRoleType::RemitTo;

        freeTextInvoiceHeaderFooterTmp.SalesAdministratorPhone = electronicAddress.Locator;


        select firstonly RecId from taxTransWET where
            taxTransWET.Voucher == _custInvoiceJour.LedgerVoucher
            && taxTransWET.TaxCode == #WET;
        if (taxTransWET.RecId)
        {
            freeTextInvoiceHeaderFooterTmp.KPMGShowWET = NoYes::Yes;
        }
        //MPJ_6030_7435_FreeTextInvReportDesign - END

    }

    /// <summary>
    /// Populates the Invoice details information into the <c>FreeTextInvoiceTmp</c> table buffer.
    /// </summary>
    /// <param name="_custInvoiceJour">
    /// The <c>CustInvoiceJour</c> record that has the invoice header information.
    /// </param>
    /// <param name="_custInvoiceTrans">
    /// The <c>CustInvoiceTrans</c> record that has the invoice details information.
    /// </param>
    /// <param name="_taxSpec">
    /// The <c>TaxSpec</c> class instance that has the taxes information.
    /// </param>
    /// <param name="_custPaymSchedLine">
    /// The <c>CustPaymSchedLine</c> record that has the payment schedules information.
    /// </param>
    /// <param name="_prepaymentCustTrans">
    /// The <c>CustTrans</c> record that has the prepayment information.
    /// </param>
    /// <param name="_prepaymentTaxTrans">
    /// The <c>TaxTrans</c> record that has the prepayment taxes information.
    /// </param>
    protected void populateFreeTextInvoiceTmp(
        CustInvoiceJour _custInvoiceJour,
        CustInvoiceTrans _custInvoiceTrans,
        TaxSpec _taxSpec,
        CustPaymSchedLine _custPaymSchedLine,
        CustTrans _prepaymentCustTrans,
        TaxTrans _prepaymentTaxTrans)
    {
        next populateFreeTextInvoiceTmp(
            _custInvoiceJour,
            _custInvoiceTrans,
            _taxSpec,
            _custPaymSchedLine,
            _prepaymentCustTrans,
             _prepaymentTaxTrans);

        //MPJ_6030_7435_FreeTextInvReportDesign - START
        TaxTrans    taxTransWET;

        select sum(TaxAmount) from taxTransWET where
            taxTransWET.Voucher == custInvoiceJour.LedgerVoucher
            && taxTransWET.SourceRecId == _custInvoiceTrans.RecId
            && taxTransWET.SourceTableId == tableNum(CUSTINVOICETRANS)
            && taxTransWET.TaxCode == #WET;
        if (taxTransWET.TaxAmount)
        {
            freeTextInvoiceTmp.KPMGWETTAXAmount = abs(taxTransWET.TaxAmount);
            freeTextInvoiceTmp.SalesBalance -= taxTransWET.TaxAmount;
            freeTextInvoiceTmp.Sumtax += taxTransWET.TaxAmount;
            freeTextInvoiceTmp.LineAmountInclTax += freeTextInvoiceTmp.KPMGWETTAXAmount;
        }
        //MPJ_6030_7435_FreeTextInvReportDesign - START
    }
